/**
 * Reseller attribution capture — Wave 6.
 *
 * THE GAP THIS CLOSES: Order.resellerId and the delivered-order wallet
 * credit (src/orders/delivered-hooks.ts) existed, but nothing ever set
 * Order.resellerId — there was no reseller code, no share link and no
 * checkout capture, so reseller credit could never fire. The chain now:
 *
 *   Reseller.code (DB, unique, generated by src/reseller/store.ts)
 *     -> share link: <storefront>/?ref=CODE
 *     -> <ResellerRefCapture> (mounted in the storefront shell) stores
 *        { code, capturedAt } in localStorage on ANY storefront page
 *     -> the checkout page includes the stored code in the order create
 *        payload while it is inside the attribution window (30 days
 *        from capture)
 *     -> the server resolves code -> Reseller (ACTIVE only — see
 *        resolveResellerAttribution in store.ts) and createOrderRecord
 *        persists Order.resellerId at create time.
 *
 * This module is the shared, client-safe half: constants, the code
 * shape/generation, and the localStorage helpers (window-guarded, the
 * same conventions as src/lib/numerals.ts). The DB half (generation
 * persistence, lazy backfill, resolution) lives in store.ts.
 */

/** localStorage key for the captured referral code (wave-6 contract). */
export const RESELLER_REF_STORAGE_KEY = "advance-ecommerce:reseller-ref";

/** Attribution window: a captured code attributes orders placed within
 *  30 days of capture. After that the stored ref is ignored (and
 *  cleared on read). */
export const RESELLER_ATTRIBUTION_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Code alphabet: URL-safe and confusion-free — no I, L, O (letter/ digit
 * lookalikes), no 0 or 1. 31 symbols, 8 chars ≈ 8.5e11 combinations;
 * the DB unique constraint + retry in store.ts covers the rest.
 */
export const RESELLER_CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
export const RESELLER_CODE_LENGTH = 8;

/**
 * Normalize a raw code (URL param, API payload, stored value) to its
 * canonical form: trimmed, uppercased, exactly RESELLER_CODE_LENGTH
 * alphabet characters. Returns null for anything else — callers treat
 * null as "no attribution", never as an error.
 */
export function normalizeResellerCode(input: unknown): string | null {
  if (typeof input !== "string") return null;
  const code = input.trim().toUpperCase();
  if (code.length !== RESELLER_CODE_LENGTH) return null;
  for (const ch of code) {
    if (!RESELLER_CODE_ALPHABET.includes(ch)) return null;
  }
  return code;
}

/**
 * Generate a fresh code. Uses Web Crypto (available in Node 19+ and
 * every browser) with rejection sampling so every alphabet symbol is
 * equally likely — no modulo bias.
 */
export function generateResellerCode(): string {
  const alphabet = RESELLER_CODE_ALPHABET;
  // Largest multiple of the alphabet size that fits in a byte.
  const limit = Math.floor(256 / alphabet.length) * alphabet.length;
  const out: string[] = [];
  while (out.length < RESELLER_CODE_LENGTH) {
    const bytes = new Uint8Array(RESELLER_CODE_LENGTH * 2);
    globalThis.crypto.getRandomValues(bytes);
    for (const b of bytes) {
      if (b >= limit) continue;
      out.push(alphabet[b % alphabet.length] as string);
      if (out.length === RESELLER_CODE_LENGTH) break;
    }
  }
  return out.join("");
}

/* ------------------------------------------------------------------ */
/* Browser storage (window-guarded; no-ops during SSR)                 */
/* ------------------------------------------------------------------ */

export interface StoredResellerRef {
  code: string;
  /** Epoch ms when the ?ref= link was captured. */
  capturedAt: number;
}

/** Persist a captured code with the capture timestamp. Invalid codes
 *  are ignored — a malformed ?ref= can never poison later checkouts. */
export function storeResellerRef(code: string): void {
  if (typeof window === "undefined") return;
  const normalized = normalizeResellerCode(code);
  if (!normalized) return;
  try {
    const value: StoredResellerRef = { code: normalized, capturedAt: Date.now() };
    window.localStorage.setItem(RESELLER_REF_STORAGE_KEY, JSON.stringify(value));
  } catch {
    // Storage unavailable (private mode etc.) — attribution is
    // best-effort and must never break the storefront.
  }
}

/**
 * The stored code when it is still inside the attribution window, else
 * null. Expired or malformed values are cleared on read so a stale ref
 * cannot attribute (or be retried) forever.
 */
export function readStoredResellerRef(now: number = Date.now()): string | null {
  if (typeof window === "undefined") return null;
  let raw: string | null = null;
  try {
    raw = window.localStorage.getItem(RESELLER_REF_STORAGE_KEY);
  } catch {
    return null;
  }
  if (!raw) return null;
  let parsed: Partial<StoredResellerRef> | null = null;
  try {
    parsed = JSON.parse(raw) as Partial<StoredResellerRef> | null;
  } catch {
    parsed = null;
  }
  const code = normalizeResellerCode(parsed?.code);
  const capturedAt = typeof parsed?.capturedAt === "number" ? parsed.capturedAt : NaN;
  if (!code || !Number.isFinite(capturedAt) || now - capturedAt > RESELLER_ATTRIBUTION_WINDOW_MS) {
    clearStoredResellerRef();
    return null;
  }
  return code;
}

export function clearStoredResellerRef(): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.removeItem(RESELLER_REF_STORAGE_KEY);
  } catch {
    // Nothing to clear if storage itself is unavailable.
  }
}
